INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Hardware-Konfiguration
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann die Hardware-Konfiguration unabhängig von den Anforderungen der Software erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Software bestimmt Hardwarebedarf"}, {"text": "Ja", "correct": false, "because": "Inkompatibilität beeinträchtigt Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Hardware-Konfiguration immer die Kompatibilität der Komponenten berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Inkompatible Teile führen zu Fehlern"}, {"text": "Nein", "correct": false, "because": "Kompatibilität ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Hardware-Konfiguration abgeschlossen, sobald die Hauptkomponenten ausgewählt sind?', 2, '[{"text": "Nein", "correct": true, "because": "Feinabstimmung und Tests nötig"}, {"text": "Ja", "correct": false, "because": "Prozess umfasst mehr"}]'),
('00000000-0000-0000-0000-000000000000', 'Können bei der Hardware-Konfiguration die Kosten ignoriert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Budget beeinflusst Auswahl"}, {"text": "Ja", "correct": false, "because": "Kosten sind relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine Hardware-Konfiguration immer zukunftssicher?', 2, '[{"text": "Nein", "correct": true, "because": "Technologischer Fortschritt begrenzt Dauer"}, {"text": "Ja", "correct": false, "because": "Zukunftssicherheit nicht garantiert"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt hat bei der Hardware-Konfiguration die höchste Priorität?', 3, '[{"text": "Kundenanforderungen", "correct": true, "because": "Bestimmen Leistung und Funktion"}, {"text": "Kostenminimierung", "correct": false, "because": "Wichtig, aber sekundär"}, {"text": "Markenpräferenz", "correct": false, "because": "Persönlich, nicht technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponente wird bei der Hardware-Konfiguration zuerst ausgewählt?', 2, '[{"text": "Prozessor", "correct": true, "because": "Definiert Basisleistung"}, {"text": "Netzteil", "correct": false, "because": "Abhängig von anderen Teilen"}, {"text": "Monitor", "correct": false, "because": "Peripheriegerät"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wird oft für die Hardware-Konfiguration verwendet?', 2, '[{"text": "PC-Konfigurator", "correct": true, "because": "Hilft bei Komponentenauswahl"}, {"text": "Textverarbeitung", "correct": false, "because": "Nicht technisch"}, {"text": "Betriebssystem", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor kann die Hardware-Konfiguration einschränken?', 3, '[{"text": "Budget", "correct": true, "because": "Begrenzt Auswahlmöglichkeiten"}, {"text": "Farbe der Komponenten", "correct": false, "because": "Ästhetisch, nicht funktional"}, {"text": "Verfügbarkeit von Software", "correct": false, "because": "Nachgelagert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die Hardware-Konfiguration primär?', 2, '[{"text": "Optimale Systemleistung", "correct": true, "because": "Erfüllt Anforderungen"}, {"text": "Minimale Kosten", "correct": false, "because": "Wichtig, aber sekundär"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch, nicht primär"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten müssen bei der Hardware-Konfiguration abgestimmt werden?', 4, '[{"text": "Prozessor", "correct": true, "because": "Kern der Leistung"}, {"text": "Mainboard", "correct": true, "because": "Verbindet Komponenten"}, {"text": "Arbeitsspeicher", "correct": true, "because": "Beeinflusst Geschwindigkeit"}, {"text": "Tastatur", "correct": false, "because": "Peripheriegerät"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Hardware-Konfiguration?', 3, '[{"text": "Softwareanforderungen", "correct": true, "because": "Bestimmen Leistungsbedarf"}, {"text": "Budget", "correct": true, "because": "Begrenzt Auswahl"}, {"text": "Zukünftige Erweiterbarkeit", "correct": true, "because": "Langfristige Nutzung"}, {"text": "Farbe der Gehäuse", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken können bei der Hardware-Konfiguration auftreten?', 3, '[{"text": "Inkompatibilität", "correct": true, "because": "Komponenten passen nicht"}, {"text": "Überschreitung des Budgets", "correct": true, "because": "Kosten außer Kontrolle"}, {"text": "Unzureichende Leistung", "correct": true, "because": "Software läuft nicht"}, {"text": "Falsche Lieferadresse", "correct": false, "because": "Logistisch, nicht technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Hardware-Konfiguration?', 4, '[{"text": "Anforderungsanalyse", "correct": true, "because": "Basis der Planung"}, {"text": "Komponentenauswahl", "correct": true, "because": "Bestimmt System"}, {"text": "Kompatibilitätsprüfung", "correct": true, "because": "Sichert Funktion"}, {"text": "Softwareentwicklung", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien machen eine Hardware-Konfiguration zukunftssicher?', 3, '[{"text": "Erweiterbarkeit", "correct": true, "because": "Ermöglicht Upgrades"}, {"text": "Leistungsreserven", "correct": true, "because": "Für zukünftige Software"}, {"text": "Aktuelle Standards", "correct": true, "because": "Kompatibilität mit Neuerungen"}, {"text": "Minimale Kosten", "correct": false, "because": "Nicht primär zukunftssicher"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Hardware-Konfiguration berücksichtigt Softwareanforderungen. b) Kompatibilität der Komponenten ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Software ja, Kompatibilität nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Budget beeinflusst die Hardware-Konfiguration. b) Der Prozessor ist die letzte Wahl bei der Konfiguration.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Budget ja, Prozessor oft zuerst"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Hardware-Konfiguration umfasst Kompatibilitätsprüfung. b) Zukunftssicherheit ist immer garantiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prüfung ja, Zukunft nicht sicher"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Hardware-Konfiguration beginnt mit der Anforderungsanalyse. b) Kosten spielen keine Rolle bei der Auswahl.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Analyse ja, Kosten relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Erweiterbarkeit ist ein Ziel der Hardware-Konfiguration. b) Die Konfiguration endet mit der Komponentenauswahl.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Erweiterbarkeit ja, Tests folgen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

